{#- dacs-font: one font on every server — Liberation Sans (Arial's letter widths) shipped in the app
    (public/fonts), so a print measures and looks the same on local and live (docs/print-formats.md › Font) -#}
{%- set dacs_base = frappe.utils.get_url() -%}
<style>
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Regular.ttf') format('truetype'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Bold.ttf') format('truetype'); font-weight: bold; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Italic.ttf') format('truetype'); font-weight: normal; font-style: italic; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-BoldItalic.ttf') format('truetype'); font-weight: bold; font-style: italic; }
body, body * { font-family: Arial !important; }
/* uniform top margin: the PDF page header (letter head, or the format's own company / store header) starts
   10mm from the top of the paper on every format (Frappe's header template pulls a letter head to the edge) */
body[onload] .wrapper > :first-child { margin-top: -7.5mm !important; }
</style>
<div id="footer-html" class="visible-pdf"><p class="text-center small page-number visible-pdf" style="font-size:7.5pt;">Page <span class="page"></span> of <span class="topage"></span></p></div>
{%- if doc.company -%}
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- else -%}
{%- set default_company = frappe.db.get_single_value('Global Defaults', 'default_company') -%}
{%- set company = frappe.get_doc("Company", default_company) if default_company else None -%}
{%- endif -%}

{# ---------------- MERGE ITEMS ---------------- #}
{# ---------------- MERGE ITEMS ---------------- #}
{%- set merged_groups = {} -%}
{%- for item in doc.items -%}
    {%- set group_key = "Panel" if doc.work_type == "Panel Job Work" else (frappe.db.get_value("Item", item.item_code, "custom_item_type") or "Uncategorized") -%}
    {%- set stock_uom = frappe.db.get_value("Item", item.item_code, "stock_uom") -%}
    {%- set qty = item.qty | float if item.qty else (item.ordered_qty | float if item.ordered_qty else 0) -%}
    {%- if group_key in merged_groups -%}
        {%- set _ = merged_groups[group_key].update({'qty': merged_groups[group_key].qty + qty}) -%}
    {%- else -%}
        {%- set _ = merged_groups.update({group_key: {'type_name': group_key, 'uom': stock_uom or "Nos", 'qty': qty}}) -%}
    {%- endif -%}
{%- endfor -%}
{%- set final_groups_list = merged_groups.values() | list -%}

{# ---------------- JOBBER & ADDRESS LOGIC ---------------- #}
{%- set jobber_id = doc.panel_jobber if doc.work_type == "Panel Job Work" else doc.full_piece_jobber -%}
{%- set jobber_name = frappe.db.get_value("Supplier", jobber_id, "supplier_name") or jobber_id -%}
{%- set jobber_address_display = "" -%}

{%- if jobber_id -%}
    {%- set addr_link = frappe.get_all("Dynamic Link", 
        filters={"link_doctype": "Supplier", "link_name": jobber_id, "parenttype": "Address"}, 
        fields=["parent"], limit=1) -%}

    {%- if addr_link -%}
        {%- set addr_doc = frappe.get_doc("Address", addr_link[0].parent) -%}
        {%- set addr_parts = [] -%}
        {%- if addr_doc.address_line1 %}{% set _ = addr_parts.append(addr_doc.address_line1) %}{% endif -%}
        {%- if addr_doc.address_line2 %}{% set _ = addr_parts.append(addr_doc.address_line2) %}{% endif -%}
        {%- if addr_doc.city %}{% set _ = addr_parts.append(addr_doc.city) %}{% endif -%}
        {%- if addr_doc.pincode %}{% set _ = addr_parts.append(addr_doc.pincode) %}{% endif -%}
        {%- set jobber_address_display = addr_parts | join(", ") -%}
    {%- endif -%}
{%- endif -%}

{# ---------------- PAGINATION SETTINGS ---------------- #}
{% set chunk_size = 13 %} 
{% set total_groups = final_groups_list|length %}
{% set pages = (total_groups // chunk_size) + (1 if total_groups % chunk_size else 0) %}
{% if pages == 0 %}{% set pages = 1 %}{% endif %}

<style>
/* PDF page margins (wkhtmltopdf reads them from this rule, frappe.utils.pdf): top and bottom both set — with
   the page-number footer and no bottom margin the top margin is dropped. PDF only, not a margin on the page box.
   Not on builder formats: their letter head / heading is the PDF page header, which a top margin rule squeezes out. */
.print-format { margin-top: 10mm; margin-bottom: 10mm; }
@media print { body .print-format { margin: 0 !important; } }
.print-format > .page-break:last-child { page-break-after: auto; }
/* terms written in the editor carry its "height: 100%" and scroll bars: inside the page box they stretched to the
   page and showed scroll arrows — the text keeps its own height */
.print-format .ql-editor { height: auto !important; overflow: visible !important; padding: 0 !important; }
.print-format .ql-editor p { margin: 0 !important; }
    @page { size: A4; margin: 10mm; }
    body { font-family: Arial, sans-serif; font-size: 9pt; margin: 0; padding: 0; }

    .wrapper {
        width: 100%;
        height: 260mm; 
        border: 2px solid #000;
        position: relative;
        box-sizing: border-box;
    }

    table { width: 100%; border-collapse: collapse; table-layout: fixed; }

    .title-banner {
        text-align: center; font-weight: bold; font-size: 12pt; letter-spacing: 1px; padding: 5px;
        border-bottom: 2px solid #000; background: #f2f2f2;
    }

    .header-table td, .jobber-table td { border-bottom: 1px solid #000; padding: 6px; vertical-align: top; }

    .items-table th { border-bottom: 2px solid #000; border-right: 1px solid #000; padding: 8px; background: #eee; }
    .items-table td { border-bottom: 1px dotted #888; border-right: 1px solid #000; padding: 6px 8px; height: 30px; }
    .items-table th:last-child, .items-table td:last-child { border-right: none; }

    .total-row td { border-top: 1px solid #000; border-bottom: 1px solid #000; padding: 8px; font-weight: bold; }

    .signature-table { position: absolute; bottom: 0; width: 100%; }
    .signature-table td {
        height: 110px; 
        text-align: center; border-top: 1px solid #000; border-right: 1px solid #000;
        vertical-align: top; padding-top: 10px;
    }
    .signature-table td:last-child { border-right: none; }

    .stamp-space { height: 45px; }
    .text-center { text-align: center; }
    .text-right { text-align: right; }
    .page-break { page-break-after: always; }
</style>

{% for page_num in range(pages) %}
<div class="wrapper">
    <div class="title-banner">EMBROIDERY OR PRINT WORK ORDER</div>

    <!-- HEADER -->
    <table class="header-table">
        <tr>
            <td width="20%" class="text-center">
                <img src="/files/Dacs inc Logo.jpeg" style="max-height:45px;">
            </td>
            <td width="50%" class="text-center">
                <strong style="font-size:11pt;">{{ company.company_name if company else doc.company }}</strong><br>
                Jaya Sai Towers No.40, Sajjan Rao Road, Bangalore - 560004<br>
                <strong>GSTIN:</strong> {{ company.gstin if company else '' }}
            </td>
            <td width="30%" style="border-left: 1px solid #000;">
                <strong>Order No:</strong> {{ doc.name }}<br>
                <strong>Date:</strong> {{ frappe.utils.formatdate(doc.date, "dd-MMM-yyyy") }}<br>
                <strong>Work Type:</strong> {{ doc.work_type }}
            </td>
        </tr>
    </table>

    <!-- JOBBER WITH ADDRESS -->
    <table class="jobber-table">
        <tr>
            <td>
                <strong>Issued To:</strong><br>
                <span style="font-size:10pt; font-weight:bold;">{{ jobber_name or 'Not Specified' }}</span><br>
                {{ jobber_address_display or 'No Address Found' }}
            </td>
        </tr>
    </table>

    <!-- ITEMS -->
    <table class="items-table">
        <thead>
            <tr>
                <th width="10%">Sr</th>
                <th width="65%">Item Type / Category Description</th>
                <th width="25%">Qty</th>
            </tr>
        </thead>
        <tbody>
            {% set start_idx = page_num * chunk_size %}
            {% set current_items = final_groups_list[start_idx : start_idx + chunk_size] %}

            {% for group in current_items %}
            <tr>
                <td class="text-center">{{ loop.index + start_idx }}</td>
                <td><strong>{{ group.type_name }}</strong></td>
                <td class="text-center">{{ "{:,.2f}".format(group.qty) }} {{ group.uom }}</td>
            </tr>
            {% endfor %}

            {# Filler rows #}
            {% set filler_count = chunk_size - current_items|length %}
            {% for i in range(filler_count) %}
            <tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr>
            {% endfor %}
        </tbody>
    </table>

    {% if page_num + 1 == pages %}
        <table class="total-row">
            <tr>
                <td width="75%" class="text-right">Grand Total Quantity:</td>
                <td width="25%" class="text-center" style="border-left: 1px solid #000;">
                    {% set grand_total = namespace(v=0) %}
                    {% for g in final_groups_list %}{% set grand_total.v = grand_total.v + g.qty %}{% endfor %}
                    {{ "{:,.2f}".format(grand_total.v) }}
                </td>
            </tr>
        </table>
        <div style="padding: 8px; min-height: 35px;">
           <strong>Remarks / Instructions:</strong> 
{%- if doc.notes -%}
    {%- set clean_notes = doc.notes -%}
    {%- if "Comment:" in doc.notes -%}
        {%- set clean_notes = doc.notes.split("Comment:")[-1].strip() -%}
    {%- endif -%}
    {{ clean_notes }}
{%- else -%}
    None
{%- endif -%}
        </div>
    {% else %}
        <div style="padding: 10px; text-align: right; font-style: italic;">Continued...</div>
    {% endif %}

    <!-- SIGNATURES -->
    <table class="signature-table">
        <tr>
            <td width="33%">
                <div class="stamp-space"></div>
                ______________________<br>
                Receiver's Signature
            </td>
            <td width="33%">
                <div class="stamp-space"></div>
                ______________________<br>
                Verified By
            </td>
            <td width="34%">
                For <strong>{{ company.company_name if company else 'Dac\'s Inc' }}</strong>
                <div class="stamp-space"></div>
                ______________________<br>
                Authorised Signatory
            </td>
        </tr>
    </table>
</div>

{% if not loop.last %}<div class="page-break"></div>{% endif %}
{% endfor %}
